grant select, insert, update, delete on storage.objects to authenticated;
create policy "Users manage their own resume files" on storage.objects for all to authenticated using (bucket_id = 'resumes' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'resumes' and (storage.foldername(name))[1] = auth.uid()::text);